package com.amit.jobagent.matching;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import org.springframework.core.io.ClassPathResource;import org.springframework.stereotype.Component;
@Component public class PromptCatalog{public final String system,inputTemplate,schema,promptChecksum,schemaChecksum;public PromptCatalog(){system=read("prompts/job-evaluation/v1/system.md");inputTemplate=read("prompts/job-evaluation/v1/input-template.md");schema=read("prompts/job-evaluation/v1/schema.json");promptChecksum=hash(system+"\n"+inputTemplate);schemaChecksum=hash(schema);}private static String read(String p){try{return new String(new ClassPathResource(p).getInputStream().readAllBytes(),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Required prompt resource is missing: "+p,e);}}static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
